/**
 * Typed plugin routes. A portal learns the routes of the plugins of its repository from
 * `src/codi-routes.d.ts`, generated by `codi portal typegen` (and `codi portal build`): a
 * module augmentation of `PluginRouteRegistry`, keyed by plugin name then route key, with
 * the access level and the query, body and response types declared by the plugin's route
 * contract (plugin.yaml `spec.routes.types`).
 *
 * ```ts
 * const levels = client.routes("levels", server.key, instance); // instance: { bot, instance }
 * const board = await levels.call("GET /leaderboard", { query: { limit: 10 } }); // board.items…
 * const poll = await client.routes("polls", server.key, p).call("GET /polls/:id", { params: { id } });
 * ```
 */
import type { CallOptions, Query } from "./client.ts";
import type {
  OnboardingAnswers,
  OnboardingCompleteResponse,
  OnboardingSteps,
} from "./onboarding.ts";
import type { Leaderboard, TicketList, TicketStatus } from "./showcase.ts";
import type { Json } from "./types.ts";

export type RouteMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
/** "<METHOD> /path", `:name` segments being parameters: "GET /polls/:id". */
export type RouteKey = `${RouteMethod} /${string}`;
/** Access level of a route (`definePlugin({ routes })`). */
export type RouteAccess = "public" | "member" | "moderator" | "admin";

/** `{ id: string }` for "GET /polls/:id". */
export type RouteParams<K extends string> = K extends `${string}/:${infer Rest}`
  ? Rest extends `${infer Name}/${infer Tail}`
    ? { [P in Name]: string } & RouteParams<`/${Tail}`>
    : { [P in Rest]: string }
  : {};

/** A route whose plugin declares no types: any query and body, a JSON response. */
export interface UntypedRoute {
  query?: Query;
  body?: unknown;
  response: Json;
}

/**
 * One route of `PluginRouteRegistry`: its access level and, when the plugin's contract
 * `Contract` declares route `K`, its `query`, `body` and `response` (absent: `204`).
 */
export type RouteEntry<
  A extends RouteAccess = RouteAccess,
  Contract = {},
  K extends string = never,
> = { readonly access: A } & ([K] extends [never]
  ? UntypedRoute
  : K extends keyof Contract
    ? Contract[K]
    : UntypedRoute);

/**
 * Routes of the plugins of the repository, by plugin name then route key. Empty here:
 * `src/codi-routes.d.ts` (generated by `codi portal typegen`) fills it.
 */
export interface PluginRouteRegistry {}

/** levels `GET /me`: the viewer's own standing. */
export interface LevelsStanding {
  userId: string;
  /** From 1, null when the viewer has no XP yet. */
  rank: number | null;
  xp: number;
  level: number;
  /** XP earned inside the current level. */
  current: number;
  /** XP needed for the next level. */
  needed: number;
}

/** polls `GET /polls/:id`. */
export interface PollResults {
  id: string;
  question: string;
  status: "open" | "closed";
  multiple: boolean;
  createdAt: string;
  closesAt: string;
  closedAt: string | null;
  choices: { label: string; votes: number }[];
  voters: number;
}

/**
 * Routes of the official plugins (the `codi` source), used for a plugin that the generated
 * registry does not list: the reference portal type-checks in a repository without them.
 */
export interface OfficialPluginRoutes {
  levels: {
    "GET /leaderboard": {
      readonly access: "public";
      query: { limit?: number };
      response: Leaderboard;
    };
    "GET /me": { readonly access: "member"; response: LevelsStanding };
  };
  polls: { "GET /polls/:id": { readonly access: "public"; response: PollResults } };
  tickets: {
    "GET /tickets": {
      readonly access: "moderator";
      query: { status?: TicketStatus };
      response: TicketList;
    };
    "GET /tickets/:id": RouteEntry<"moderator">;
  };
  onboarding: {
    "GET /steps": { readonly access: "member"; response: OnboardingSteps };
    "POST /complete": {
      readonly access: "member";
      body: { answers: OnboardingAnswers };
      response: OnboardingCompleteResponse;
    };
  };
}

/** The routes of plugin `N`: generated registry, else official plugin, else untyped. */
export type RoutesOf<N extends string> = N extends keyof PluginRouteRegistry
  ? PluginRouteRegistry[N]
  : N extends keyof OfficialPluginRoutes
    ? OfficialPluginRoutes[N]
    : { [K in RouteKey]: RouteEntry };

/** Route keys of plugin `N` (optionally only those of `M` methods). */
export type RouteKeyOf<N extends string, M extends RouteMethod = RouteMethod> = Extract<
  keyof RoutesOf<N>,
  `${M} /${string}`
>;

/** The JSON a route answers with (`undefined` for routes declaring no response: 204). */
export type RouteResponseOf<E> = E extends { response: infer R } ? R : undefined;

type ParamsArg<K extends string> = keyof RouteParams<K> extends never
  ? { params?: Record<string, never> }
  : { params: RouteParams<K> };
type QueryArg<E> = E extends { query: infer Q }
  ? {} extends Q
    ? { query?: Q }
    : { query: Q }
  : E extends { query?: infer Q }
    ? { query?: Q }
    : { query?: undefined };
type BodyArg<E> = E extends { body: infer B }
  ? { body: B }
  : E extends { body?: infer B }
    ? { body?: B }
    : { body?: undefined };

/** What a call needs: `params` (from the key), `query` and `body` (as declared). */
export type RouteInput<K extends string, E> = ParamsArg<K> & QueryArg<E> & BodyArg<E>;
export type RouteCallOptions<K extends string, E> = RouteInput<K, E> &
  CallOptions & { headers?: Record<string, string> };

/** Makes the options argument optional when nothing in it is required. */
export type OptionalArg<T> = {} extends T ? [options?: T] : [options: T];

/** Typed calls to the routes of one instance of plugin `N`. */
export interface TypedPluginRoutes<N extends string> {
  readonly plugin: N;
  readonly server: string;
  readonly bot: string;
  readonly instance: string;
  /** Calls a route: `call("GET /polls/:id", { params: { id } })`. */
  call<K extends RouteKeyOf<N> & string>(
    this: void,
    route: K,
    ...options: OptionalArg<RouteCallOptions<K, RoutesOf<N>[K]>>
  ): Promise<RouteResponseOf<RoutesOf<N>[K]>>;
  /** Absolute URL of a route (`GET` routes: links, `<img src>`, EventSource…). */
  url<K extends RouteKeyOf<N> & string>(
    this: void,
    route: K,
    ...options: OptionalArg<RouteInput<K, RoutesOf<N>[K]>>
  ): string;
}

/** Splits "GET /polls/:id" with `{ id: "4" }` into `["GET", "/polls/4"]`. */
export function resolveRoute(
  route: string,
  params: Record<string, string | number> | undefined = {},
): [method: RouteMethod, path: string] {
  const space = route.indexOf(" ");
  const method = route.slice(0, space) as RouteMethod;
  if (space < 0 || !["GET", "POST", "PUT", "PATCH", "DELETE"].includes(method))
    throw new Error(`@codi/client: invalid route key ${JSON.stringify(route)}`);
  const path = route
    .slice(space + 1)
    .split("/")
    .map((segment) => {
      if (!segment.startsWith(":")) return segment;
      const value = params[segment.slice(1)];
      if (value === undefined || value === "")
        throw new Error(`@codi/client: missing parameter ${segment.slice(1)} of ${route}`);
      // A value taken from the page URL must never climb out of the route ("..": another
      // route of the instance, another plugin, another API endpoint with the viewer's
      // cookies). Dots are encoded too, so no segment can be a dot-segment; the runtime
      // reads %2E as a literal dot.
      if (value === "." || value === "..")
        throw new Error(
          `@codi/client: invalid parameter ${segment.slice(1)} of ${route}: ${value}`,
        );
      return encodeURIComponent(String(value)).replace(/\./g, "%2E");
    })
    .join("/");
  return [method, path];
}
